CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE admins(id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY, admin_id TEXT NOT NULL REFERENCES admins(id) ON DELETE CASCADE, csrf TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE login_attempts(key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at INTEGER NOT NULL);
CREATE TABLE media(id TEXT PRIMARY KEY, storage_key TEXT NOT NULL, source TEXT NOT NULL, filename TEXT NOT NULL, mime_type TEXT NOT NULL, file_size INTEGER NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, alt_text TEXT NOT NULL, category TEXT NOT NULL, variants TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE events(id TEXT PRIMARY KEY, slug TEXT UNIQUE NOT NULL, title TEXT NOT NULL, short_description TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', date TEXT, end_date TEXT, time TEXT NOT NULL DEFAULT '', venue TEXT NOT NULL DEFAULT '', categories TEXT NOT NULL DEFAULT '[]', event_type TEXT NOT NULL DEFAULT '', poster_id TEXT REFERENCES media(id) ON DELETE RESTRICT, cover_id TEXT REFERENCES media(id) ON DELETE RESTRICT, status TEXT NOT NULL CHECK(status IN ('DRAFT','UPCOMING','COMPLETED','ARCHIVED')), published INTEGER NOT NULL DEFAULT 0, featured INTEGER NOT NULL DEFAULT 0, design TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, published_at TEXT);
CREATE TABLE gallery_items(id TEXT PRIMARY KEY, media_id TEXT NOT NULL REFERENCES media(id) ON DELETE RESTRICT, event_id TEXT REFERENCES events(id) ON DELETE RESTRICT, title TEXT NOT NULL, caption TEXT NOT NULL DEFAULT '', category TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, wide INTEGER NOT NULL DEFAULT 0, featured INTEGER NOT NULL DEFAULT 0, published INTEGER NOT NULL DEFAULT 0, focal_position TEXT NOT NULL DEFAULT 'center', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE documents(name TEXT PRIMARY KEY, draft TEXT NOT NULL, published TEXT NOT NULL, updated_at TEXT NOT NULL, published_at TEXT NOT NULL);
CREATE TABLE document_media(document_name TEXT NOT NULL REFERENCES documents(name), revision TEXT NOT NULL, slot TEXT NOT NULL, media_id TEXT NOT NULL REFERENCES media(id) ON DELETE RESTRICT, PRIMARY KEY(document_name, revision, slot));
CREATE TABLE document_events(document_name TEXT NOT NULL REFERENCES documents(name), revision TEXT NOT NULL, slot TEXT NOT NULL, event_id TEXT NOT NULL REFERENCES events(id) ON DELETE RESTRICT, PRIMARY KEY(document_name, revision, slot));
CREATE TABLE activity(id INTEGER PRIMARY KEY AUTOINCREMENT, admin_id TEXT REFERENCES admins(id), action TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX gallery_event ON gallery_items(event_id);
CREATE INDEX session_expiry ON sessions(expires_at);
CREATE INDEX event_visibility ON events(published,status);
